section.p:
Eight independent depth planes, each offset by a small mouse-follow delta
and driven by an eased scroll value. Depth factors run 0.06 through 0.86;
the fossil and the plant reveal themselves as the stage enters the viewport.

body.script:
(function(){
  'use strict';

  document.getElementById('yr').textContent = new Date().getFullYear();

  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');

  /* ---------- SCROLL PARALLAX + MOUSE PARALLAX ---------- */
  var stage  = document.getElementById('stage');
  var layers = [].slice.call(document.querySelectorAll('.layer'));

  var scrollY = 0, targetScroll = 0;
  var mx = 0, my = 0, tmx = 0, tmy = 0;

  function readScroll(){
    if(!stage) return;
    var rect = stage.getBoundingClientRect();
    // -1 .. 1 as the stage passes through the viewport
    var p = 1 - (rect.top + rect.height) / (window.innerHeight + rect.height);
    targetScroll = Math.max(-1, Math.min(1, p * 2 - 1));
  }

  window.addEventListener('scroll', readScroll, {passive:true});
  window.addEventListener('resize', readScroll);

  window.addEventListener('mousemove', function(e){
    if(reduce.matches) return;
    tmx = (e.clientX / window.innerWidth  - 0.5) * 2;
    tmy = (e.clientY / window.innerHeight - 0.5) * 2;
  }, {passive:true});

  function tick(){
    if(reduce.matches){
      layers.forEach(function(l){ l.style.transform = ''; });
      requestAnimationFrame(tick);
      return;
    }
    // eased follow
    scrollY += (targetScroll - scrollY) * 0.09;
    mx += (tmx - mx) * 0.06;
    my += (tmy - my) * 0.06;

    layers.forEach(function(l){
      var d = parseFloat(l.dataset.depth) || 0;
      var yShift = -scrollY * d * 190;
      var mxShift = mx * d * 5;      // 2-5px mouse offset budget
      var myShift = my * d * 5;
      l.style.transform = 'translate3d(' + mxShift.toFixed(2) + 'px,' +
                           (yShift + myShift).toFixed(2) + 'px,0)';
    });
    requestAnimationFrame(tick);
  }

  readScroll();
  requestAnimationFrame(tick);

  /* ---------- SCROLL-TRIGGERED REVEAL ---------- */
  var reveals = [].slice.call(document.querySelectorAll('.reveal'));

  if(reduce.matches || !('IntersectionObserver' in window)){
    reveals.forEach(function(el){ el.classList.add('in'); });
  } else {
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(en){
        if(en.isIntersecting){
          en.target.classList.add('in');
          io.unobserve(en.target);
        }
      });
    }, {rootMargin:'0px 0px -18% 0px', threshold:0.12});
    reveals.forEach(function(el){ io.observe(el); });
  }

  /* ---------- AMBIENT SOUND (default muted) ---------- */
  var btn   = document.getElementById('audioBtn');
  var label = document.getElementById('audioLabel');
  var ctx = null, gain = null, nodes = [], playing = false;

  function buildAmbient(){
    var AC = window.AudioContext || window.webkitAudioContext;
    if(!AC) return null;
    var c = new AC();
    var g = c.createGain();
    g.gain.value = 0;
    g.connect(c.destination);

    // low swamp drone
    var o1 = c.createOscillator(); o1.type = 'sine';     o1.frequency.value = 55;
    var o2 = c.createOscillator(); o2.type = 'triangle'; o2.frequency.value = 82.5;
    var og = c.createGain(); og.gain.value = 0.16;
    o1.connect(og); o2.connect(og); og.connect(g);

    // filtered noise bed
    var len = c.sampleRate * 4;
    var buf = c.createBuffer(1, len, c.sampleRate);
    var data = buf.getChannelData(0);
    for(var i=0;i<len;i++){ data[i] = (Math.random()*2-1) * 0.5; }
    var src = c.createBufferSource();
    src.buffer = buf; src.loop = true;
    var lp = c.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value = 420;
    var ng = c.createGain(); ng.gain.value = 0.05;
    src.connect(lp); lp.connect(ng); ng.connect(g);

    // slow LFO on the noise bed for "tide"
    var lfo = c.createOscillator(); lfo.frequency.value = 0.08;
    var lfoGain = c.createGain(); lfoGain.gain.value = 0.035;
    lfo.connect(lfoGain); lfoGain.connect(ng.gain);

    o1.start(); o2.start(); src.start(); lfo.start();
    return {ctx:c, master:g, nodes:[o1,o2,src,lfo]};
  }

  btn.addEventListener('click', function(){
    if(reduce.matches){ /* audio allowed regardless of motion pref */ }
    if(!ctx){
      var built = buildAmbient();
      if(!built){ label.textContent = 'Ambient: N/A'; return; }
      ctx = built.ctx; gain = built.master; nodes = built.nodes;
    }
    if(ctx.state === 'suspended'){ ctx.resume(); }

    playing = !playing;
    var now = ctx.currentTime;
    gain.gain.cancelScheduledValues(now);
    gain.gain.setValueAtTime(gain.gain.value, now);
    gain.gain.linearRampToValueAtTime(playing ? 0.22 : 0, now + 1.1);

    btn.setAttribute('aria-pressed', String(playing));
    btn.setAttribute('aria-label', 'Toggle ambient sound (currently ' + (playing ? 'on' : 'muted') + ')');
    label.textContent = 'Ambient: ' + (playing ? 'On' : 'Off');
  });

  /* pause ambient when tab is hidden */
  document.addEventListener('visibilitychange', function(){
    if(!ctx || !playing) return;
    if(document.hidden){ ctx.suspend(); } else { ctx.resume(); }
  });
})();
